current_rule_draft:
{
  "consentmanager": {
    "detectors": [
      {
        "presentMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "[id*='cmpbox']"
            }
          }
        ],
        "showingMatcher": [
          {
            "type": "css",
            "target": {
              "selector": "[id*='cmpbox']",
              "displayFilter": true
            }
          }
        ]
      }
    ],
    "methods": [
      {
        "name": "HIDE_CMP",
        "action": {
          "type": "hide",
          "target": {
            "selector": "[id*='cmpbox']"
          }
        }
      },
      {
        "name": "OPEN_OPTIONS",
        "action": {
          "type": "click",
          "target": {
            "selector": "#cmpwelcomebtncustom a"
          }
        }
      },
      {
        "name": "DO_CONSENT",
        "action": {
          "type": "consent",
          "consents": [
            {
              "type": "D",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Speichern von oder Zugriff auf Informationen auf einem Endgerät'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Speichern von oder Zugriff auf Informationen auf einem Endgerät']"
                }
              }
            },
            {
              "type": "D",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Verwendung und Weitergabe von Identifiern'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Verwendung und Weitergabe von Identifiern']"
                }
              }
            },
            {
              "type": "A",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Ausspielung von Push-Benachrichtigungen'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Ausspielung von Push-Benachrichtigungen']"
                }
              }
            },
            {
              "type": "A",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Funktionale Verwendungszwecke'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Funktionale Verwendungszwecke']"
                }
              }
            },
            {
              "type": "B",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Eigene Produkt- und Vertriebsentwicklung durch Datenanalyse, Analytics-Storage und Nutzeransprache'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Eigene Produkt- und Vertriebsentwicklung durch Datenanalyse, Analytics-Storage und Nutzeransprache']"
                }
              }
            },
            {
              "type": "E",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Anzeige von Drittinhalten (z.B. YouTube-Videos)'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Anzeige von Drittinhalten (z.B. YouTube-Videos)']"
                }
              }
            },
            {
              "type": "F",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Personalisierte Werbung und Inhalte, Messung von Werbeleistung und der Performance von Inhalten, Zielgruppenforschung sowie Entwicklung und Verbesserung von Angeboten '][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Personalisierte Werbung und Inhalte, Messung von Werbeleistung und der Performance von Inhalten, Zielgruppenforschung sowie Entwicklung und Verbesserung von Angeboten ']"
                }
              }
            },
            {
              "type": "X",
              "matcher": {
                "type": "css",
                "target": {
                  "selector": "[aria-label='Generierung einer User-ID auf Basis Ihrer E-Mail Adresse'][aria-checked='true']"
                }
              },
              "toggleAction": {
                "type": "click",
                "target": {
                  "selector": "[aria-label='Generierung einer User-ID auf Basis Ihrer E-Mail Adresse']"
                }
              }
            }
          ]
        }
      },
      {
        "name": "SAVE_CONSENT",
        "action": {
          "type": "list",
          "actions": [
            {
              "type": "wait",
              "waitTime": 500
            },
            {
              "type": "ifcss",
              "target": {
                "selector": ".cmpboxbtnyescustomdisabled"
              },
              "trueAction": {
                "type": "click",
                "target": {
                  "selector": ".cmpboxbtnrejectcustomchoices"
                }
              },
              "falseAction": {
                "type": "click",
                "target": {
                  "selector": ".cmpboxbtnyescustom"
                }
              }
            }
          ]
        }
      }
    ]
  }
}
